+ActionReply ChargeThresholdHelper::setthreshold(const QVariantMap &args)
+{
+    const QStringList batteries = getBatteries();
+
+    // Thresholds for individual batteries, keyed by their sysfs name
+    if (args.contains(u"batteries"_s)) {
+        const QVariantMap batteryArgs = args.value(u"batteries"_s).toMap();
+        const QStringList requestedBatteries = batteryArgs.keys();
+        for (const QString &battery : requestedBatteries) {
+            if (!batteries.contains(battery)) {
+                auto reply = ActionReply::HelperErrorReply();
+                reply.setErrorDescription(QStringLiteral("Unknown battery %1").arg(battery));
+                return reply;
+            }
+        }
+        for (const auto &[battery, thresholds] : batteryArgs.asKeyValueRange()) {
+            if (auto reply = setBatteryThresholds({battery}, thresholds.toMap()); reply.failed()) {
+                return reply;
+            }
+        }
+        return ActionReply();
+    }
+
+    return setBatteryThresholds(batteries, args);
+}
